Lemma y4_idx_bound : forall tl c b sh, 1 <= tl <= 12 -> 0 <= c < 2^64 -> sh = 64 - tl ->
  0 <= (c ≪ b mod 18446744073709551616) ≫ sh < 2^tl.
Proof.
